{
  "passages": [
    {
      "id": "P1",
      "text": "ENDOSCOPY NOTE - EGD AND COLONOSCOPY, SAME SESSION"
    },
    {
      "id": "P2",
      "text": "Service date: Nov 6, 2026"
    },
    {
      "id": "P3",
      "text": "Endoscopist: Anselm Wrenfield, MD (fictional)"
    },
    {
      "id": "P4",
      "text": "Instruments: Gastroscope; adult colonoscope"
    },
    {
      "id": "P5",
      "text": "Past"
    },
    {
      "id": "P6",
      "text": "history: ERCP with biliary sphincterotomy and stone extraction at another"
    },
    {
      "id": "P7",
      "text": "hospital in 2023, followed by laparoscopic cholecystectomy."
    },
    {
      "id": "P8",
      "text": "EGD"
    },
    {
      "id": "P9",
      "text": "Gastroscope passed under direct vision through the esophagus and"
    },
    {
      "id": "P10",
      "text": "stomach to the second part of the duodenum."
    },
    {
      "id": "P11",
      "text": "Patchy erythema in the antrum, no erosions or ulcers."
    },
    {
      "id": "P12",
      "text": "Biopsies, cold forceps: antrum and body for H. pylori (jar 1); duodenal"
    },
    {
      "id": "P13",
      "text": "bulb and second portion for celiac disease (jar 2)."
    },
    {
      "id": "P14",
      "text": "COLONOSCOPY"
    },
    {
      "id": "P15",
      "text": "Bite block removed; she remained in the left lateral position."
    },
    {
      "id": "P16",
      "text": "The colonoscope was inserted and advanced under direct vision."
    },
    {
      "id": "P17",
      "text": "Sigmoid colon, 30 cm: 10 mm sessile polyp, removed en bloc with a cold"
    },
    {
      "id": "P18",
      "text": "snare and retrieved (jar 3)."
    },
    {
      "id": "P19",
      "text": "Because she takes aspirin, one clip was"
    },
    {
      "id": "P20",
      "text": "placed to close the defect; no bleeding was seen before or after."
    },
    {
      "id": "P21",
      "text": "Moderate diverticulosis in the sigmoid and descending colon."
    },
    {
      "id": "P22",
      "text": "1. 2 cm hiatal hernia; mild antral erythema, biopsied."
    },
    {
      "id": "P23",
      "text": "2. Normal-appearing duodenum, biopsied for celiac disease."
    },
    {
      "id": "P24",
      "text": "3. Healed sphincterotomy at the papilla from the 2023 ERCP."
    },
    {
      "id": "P25",
      "text": "4. 10 mm sigmoid polyp removed with cold snare; prophylactic clip placed."
    }
  ],
